// ---- result shapes -------------------------------------------------------


/** Token/cost totals for one run (server `_usage`). */
export interface Usage {
  input: number
  output: number
  cache_read: number
  cache_write: number
  cost: number
}

/** One entry of the `tools` catalog. */
export interface ToolRow {
  name: string
  description: string
  approval: string
}

/** One built-in slash command. */
export interface CommandEntry {
  name: string
  description: string
}

/** One row of a directory listing (folders first, sorted). */
export interface WorkspaceEntry {
  name: string
  path: string
  kind: 'dir' | 'file'
  size: number
  hidden: boolean
}

/** One file's content: shape varies by `kind` (text/image/binary/tooLarge). */
export interface FilePayload {
  path: string
  kind: string
  size?: number
  text?: string
  total_lines?: number
  truncated?: boolean
  mime?: string
  data_url?: string
}

/** One row of the composer's `@` snapshot. */
export interface FsIndexEntry {
  path: string
  kind: 'dir' | 'file'
}

/** One project-memory note (server-side dataclass, asdict). */
export interface MemoryEntry {
  id: string
  title: string
  body: string
  created: string
  updated: string
  source: string
}

/** One file's working-tree state; plus/minus are null for untracked. */
export interface GitFileChange {
  path: string
  state: 'staged' | 'unstaged' | 'untracked'
  plus: number | null
  minus: number | null
}

/** The changes list payload. */
export interface GitChangesPayload {
  is_repo: boolean
  branch: string
  files: Array<GitFileChange>
  untracked_more: number
}

/** One commit of the graph page. */
export interface GitCommit {
  hash: string
  short: string
  parents: Array<string>
  subject: string
  author: string
  timestamp: number
  refs: Array<string>
}

/** The git_log payload. */
export interface CommitPage {
  commits: Array<GitCommit>
}

/** One file inside a commit detail. */
export interface GitShowFile {
  path: string
  additions: number
  removals: number
  diff: string
}

/** The git_show payload; found=false for an unknown commit. */
export interface GitShowPayload {
  found: boolean
  short: string
  subject: string
  files: Array<GitShowFile>
}

/** One file's unified diff. */
export interface GitDiffPayload {
  text: string
  binary: boolean
  truncated: boolean
  missing: boolean
}

/** One worktree of the overview list. */
export interface WorktreeEntry {
  path: string
  head: string
  branch: string
  timestamp: number
  bare: boolean
  detached: boolean
  current: boolean
}

/** The current worktree's counts; the overview's `status` is null outside a repo. */
export interface GitStatusPayload {
  branch: string
  staged: number
  dirty: number
  untracked: number
  clean: boolean
}

/** The git_worktrees payload. */
export interface WorktreeOverview {
  root: string
  is_repo: boolean
  is_worktree: boolean
  main: string
  branch: string
  worktrees: Array<WorktreeEntry>
  status: GitStatusPayload | null
}

/** One catalog model, annotated with key availability. */
export interface ModelEntry {
  id: string
  provider: string
  context_window: number
  max_tokens: number
  reasoning: boolean
  supports_vision: boolean
  available: boolean
  reason: string | null
  current: boolean
}

/** One session of a listing; timestamps are unix seconds. */
export interface SessionSummary {
  path: string
  name: string
  title: string
  project: string
  project_path: string
  messages: number
  current: boolean
  pinned: boolean
  created_at: number
  updated_at: number
  model: string
  derived_from: string
  workspace: 'coding' | 'zen' | 'swarm'
}


